extension BundledLocalizationCatalogV1 {
    static func v30Text(
        _ key: V30EnglishPlainKeyV1, bundle: Bundle = .main, languageLocale: Locale? = nil
    ) -> String {
        let language = languageLocale ?? Locale(identifier:
            SystemLanguageResolverV1(bundle: bundle).resolve().effectiveLanguage.rawValue)
        switch key {
        case .advancedRecurrenceActiveDates:
            return String(localized: "v30.advanced-recurrence.active-dates",
                defaultValue: "Active dates",
                bundle: bundle, locale: language, comment: "Screen: Advanced recurrence. Meaning: Names the active dates value. Role: value-row label. Arguments: none. Plural/select: none. Accessibility: The combined row exposes this label with its value to VoiceOver. Screenshot: Advanced recurrence value-row label state; no screenshot is claimed.")
        case .advancedRecurrenceAdvancedControlsHeading:
            return String(localized: "v30.advanced-recurrence.advanced-controls-heading",
                defaultValue: "Advanced exceptions and history controls",
                bundle: bundle, locale: language, comment: "Screen: Advanced recurrence. Meaning: Names the advanced controls disclosure button label. Role: button label. Arguments: none. Plural/select: none. Accessibility: Presented in the SwiftUI button label; no combined VoiceOver behavior is claimed. Screenshot: Advanced recurrence disclosure button label state; no screenshot is claimed.")
        case .advancedRecurrenceAmbiguousLocalTime:
            return String(localized: "v30.advanced-recurrence.ambiguous-local-time",
                defaultValue: "Ambiguous local time",
                bundle: bundle, locale: language, comment: "Screen: Advanced recurrence. Meaning: Names the ambiguous local time value. Role: value-row label. Arguments: none. Plural/select: none. Accessibility: The combined row exposes this label with its value to VoiceOver. Screenshot: Advanced recurrence value-row label state; no screenshot is claimed.")
        case .advancedRecurrenceBaseScheduleHeading:
            return String(localized: "v30.advanced-recurrence.base-schedule-heading",
                defaultValue: "Base schedule",
                bundle: bundle, locale: language, comment: "Screen: Advanced recurrence. Meaning: Names the base schedule heading section. Role: section heading. Arguments: none. Plural/select: none. Accessibility: The header trait and VoiceOver announce it as a section heading. Screenshot: Advanced recurrence section heading state; no screenshot is claimed.")
        case .advancedRecurrenceBoundariesDescription:
            return String(localized: "v30.advanced-recurrence.boundaries-description",
                defaultValue: "This surface does not request calendar permission, create a cloud schedule, run in the background, or claim a server result.",
                bundle: bundle, locale: language, comment: "Screen: Advanced recurrence. Meaning: Explains boundaries description in the current screen state. Role: body copy. Arguments: none. Plural/select: none. Accessibility: Read as static content by VoiceOver. Screenshot: Advanced recurrence body copy state; no screenshot is claimed.")
        case .advancedRecurrenceBoundariesHeading:
