    static func v30AdvancedRecurrenceDaily(
        interval: Int,
        bundle: Bundle = .main, languageLocale: Locale? = nil, formattingLocale: Locale = .current
    ) -> String {
        let language = languageLocale ?? Locale(identifier:
            SystemLanguageResolverV1(bundle: bundle).resolve().effectiveLanguage.rawValue)
        var options = AttributedString.LocalizationOptions()
        options.applyReplacementIndexAttribute = true
        let message = AttributedString(localized: "v30.advanced-recurrence.daily",
            defaultValue: "Every \(interval) days",
            options: options, bundle: bundle, locale: language,
            comment: "Screen: Advanced recurrence. Meaning: Daily interval pattern. Role: visible schedule summary. Arguments: interval Int aggregateCount x1. Plural/select: one/other for interval. Accessibility: Read in Base schedule.. Screenshot: Advanced recurrence visible state.")
        return v30ApplyingNumericPresentation(message, replacements: [
            1: formattedInteger(interval, regionSource: formattingLocale),
        ])
    }

