    /// Foundation chooses grammar and marks typed replacements after localized
    /// reordering. Only numeric runs receive the independent formatting locale;
    /// authored text, identifiers, punctuation, and catalog wording are copied.
    static func v30ApplyingNumericPresentation(
        _ message: AttributedString, replacements: [Int: String]
    ) -> String {
        var result = ""
        for (index, range) in message.runs[\.replacementIndex] {
            if let index, let replacement = replacements[index] {
                result += replacement
            } else {
                result += String(message[range].characters)
            }
        }
        return result
    }

    private static func v30FormattedInteger64(_ value: Int64, locale: Locale) -> String {
        let formatter = NumberFormatter()
        formatter.numberStyle = .decimal
        formatter.locale = locale
        return formatter.string(from: NSNumber(value: value)) ?? String(value)
    }
